INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 0.0, 0, "キャル", 1, 1, -363.0, 106001, 7, 0, 0.0, 7001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 0.0, 0, "コッコロ", 1, 1, -363.0, 105901, 7, 0, 0.0, 7002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 0.0, 0, "ペコリーヌ", 1, 1, -363.0, 105801, 7, 0, 0.0, 7003, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ジュエルを食べ物…\nいえ、貴重品と交換できます！", 0.0, 0, "ペコリーヌ", 1, 1, -363.0, 105801, 10, 0, 0.0, 10001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 0.0, 0, "キャル", 1, 1, -363.0, 106001, 10, 0, 0.0, 10002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 0.0, 0, "コッコロ", 1, 1, -363.0, 105901, 10, 0, 0.0, 10003, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 0.0, 2104010, "シェフィ", 2, 1, -363.0, 106401, 10, 0, 0.0, 10004, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 0.0, 0, "ペコリーヌ", 1, 1, -416.5, 105801, 12, 0, 0.0, 12001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 0.0, 0, "キャル", 1, 1, -363.0, 106001, 13, 0, 0.0, 13001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 0.0, 0, "コッコロ", 1, 1, -363.0, 105901, 13, 0, 0.0, 13002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 0.0, 2104010, "シェフィ", 2, 1, -363.0, 106401, 13, 0, 0.0, 13003, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 0.0, 0, "ペコリーヌ", 1, 1, -363.0, 105801, 13, 0, 0.0, 13004, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 0.0, 0, "コッコロ", 1, 1, -363.0, 105901, 14, 0, 0.0, 14001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 0.0, 2104010, "シェフィ", 2, 1, -363.0, 106401, 14, 0, 0.0, 14002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 0.0, 0, "ペコリーヌ", 1, 1, -363.0, 105801, 14, 0, 0.0, 14003, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 0.0, 0, "キャル", 1, 1, -363.0, 106001, 14, 0, 0.0, 14004, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 0.0, 0, "コッコロ", 1, 1, -470.0, 105901, 15, 0, 0.0, 15001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 0.0, 2104010, "シェフィ", 2, 1, -363.0, 106401, 16, 0, 0.0, 16001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 0.0, 0, "ペコリーヌ", 1, 1, -363.0, 105801, 16, 0, 0.0, 16002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 0.0, 0, "キャル", 1, 1, -363.0, 106001, 16, 0, 0.0, 16003, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 0.0, 0, "コッコロ", 1, 1, -363.0, 105901, 16, 0, 0.0, 16004, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (" こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 0.0, 0, "コッコロ", 1, 1, -363.0, 105901, 17, 0, 0.0, 17002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 0.0, 0, "キャル", 1, 1, -363.0, 106001, 25, 0, 0.0, 17004, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 0.0, 0, "コッコロ", 1, 1, -363.0, 105901, 25, 0, 0.0, 17005, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 0.0, 2104010, "シェフィ", 2, 1, -363.0, 106401, 25, 0, 0.0, 17006, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 0.0, 0, "ペコリーヌ", 1, 1, -363.0, 105801, 25, 0, 0.0, 17007, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 0.0, 0, "カリン", 1, 1, -363.0, 190801, 18, 0, 0.0, 18001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 0.0, 0, "カリン", 1, 1, -363.0, 190801, 18, 0, 0.0, 18002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 0.0, 0, "カリン", 1, 1, -470.0, 190801, 19, 0, 0.0, 19001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 0.0, 0, "カリン", 1, 1, -470.0, 190801, 19, 0, 0.0, 19002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 0.0, 0, "カリン", 1, 1, -470.0, 190801, 20, 0, 0.0, 20001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 5);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 0.0, 0, "カリン", 1, 1, -470.0, 190801, 20, 0, 0.0, 20002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 6);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 0.0, 0, "キャル", 1, 1, -363.0, 106001, 21, 0, 0.0, 21001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 0.0, 0, "コッコロ", 1, 1, -363.0, 105901, 21, 0, 0.0, 21002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 0.0, 2104010, "シェフィ", 2, 1, -363.0, 106401, 21, 0, 0.0, 21003, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 0.0, 0, "ペコリーヌ", 1, 1, -363.0, 105801, 21, 0, 0.0, 21004, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 0.0, 0, "カリン", 1, 1, -430.0, 190801, 22, 0, 0.0, 22001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 0.0, 0, "カリン", 1, 1, -430.0, 190801, 22, 0, 0.0, 22002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 0.0, 0, "カリン", 1, 1, -430.0, 190801, 23, 0, 0.0, 23001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 0.0, 0, "カリン", 1, 1, -430.0, 190801, 23, 0, 0.0, 23002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 4.08, 0, "エリコ（バレンタイン）", 1, 2, -385.0, 109001, 24, 10011, 8.0, 24001, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 5.0, 0, "エリコ（バレンタイン）", 1, 2, -385.0, 109001, 24, 10011, 8.0, 24002, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 10.11, 0, "エリコ（バレンタイン）", 1, 2, -385.0, 109001, 24, 10011, 8.0, 24003, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 4.0, 0, "エリコ（バレンタイン）", 1, 2, -385.0, 109001, 24, 10011, 8.0, 24004, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 6.0, 0, "エリコ（バレンタイン）", 1, 2, -385.0, 109001, 24, 10011, 8.0, 24005, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 5);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 0.0, 0, "エリコ（バレンタイン）", 1, 1, 0.0, 109002, 24, 10011, 0.0, 24006, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 6);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 0.0, 0, "エリコ（バレンタイン）", 1, 1, 0.0, 109002, 24, 10011, 0.0, 24007, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 7);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 0.0, 0, "エリコ（バレンタイン）", 1, 1, 0.0, 109002, 24, 10011, 0.0, 24008, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 8);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 0.0, 0, "エリコ（バレンタイン）", 1, 1, 0.0, 109002, 24, 10011, 0.0, 24009, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 9);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 0.0, 0, "エリコ（バレンタイン）", 1, 1, 0.0, 109002, 24, 10011, 0.0, 24010, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 10);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 2.12, 0, "シズル（バレンタイン）", 1, 2, -385.0, 109101, 24, 10011, 8.0, 24011, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 4.19, 0, "シズル（バレンタイン）", 5, 2, -385.0, 109101, 24, 10011, 8.0, 24012, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 2.3, 0, "シズル（バレンタイン）", 2, 4, -385.0, 109101, 24, 10011, 8.0, 24013, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 0.0, 0, "シズル（バレンタイン）", 1, 1, 0.0, 109102, 24, 10011, 0.0, 24014, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 5.23, 0, "シズル（バレンタイン）", 5, 2, -385.0, 109101, 24, 10011, 8.0, 24015, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 5);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 0.0, 0, "シズル（バレンタイン）", 1, 1, 0.0, 109102, 24, 10011, 0.0, 24016, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 6);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 5.01, 0, "シズル（バレンタイン）", 1, 2, -385.0, 109101, 24, 10011, 8.0, 24017, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 7);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 0.0, 0, "シズル（バレンタイン）", 1, 1, 0.0, 109102, 24, 10011, 0.0, 24018, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 8);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 0.0, 0, "シズル（バレンタイン）", 1, 1, 0.0, 109102, 24, 10011, 0.0, 24019, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 9);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 0.0, 0, "シズル（バレンタイン）", 1, 1, 0.0, 109102, 24, 10011, 0.0, 24020, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 10);
