INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 0.0, 0, "ペコリーヌ", 1, 1, -363.0, 105801, 43, 0, 0.0, 43001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
