INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 0.0, 0, "キャル", 1, 1, -363.0, 106001, 43, 0, 0.0, 43003, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 0.0, 0, "アメス", 1, 1, -416.5, 123001, 44, 0, 0.0, 43004, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 0.0, 0, "アメス", 1, 1, -416.5, 123001, 44, 0, 0.0, 43005, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 5.79, 0, "アメス", 1, 2, -416.5, 123001, 45, 0, 0.0, 43006, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 0.0, 0, "アメス", 1, 1, -371.5, 123001, 46, 0, 0.0, 46001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 0.0, 0, "シズル", 2, 2, -416.5, 104901, 47, 0, 0.0, 47001, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES ("ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 9.32, 0, "リノ", 1, 2, -416.5, 101101, 47, 0, 0.0, 47002, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 1);
